mapper.select:
select download_count
from sd_dataset_stat
where dataset_id = #{datasetId}

select view_count
from sd_dataset_stat
where dataset_id = #{datasetId}

mapper.update:
update sd_dataset_stat 
set view_count = view_count + 1, updated_at = now()
where dataset_id = #{datasetId}

update sd_dataset_stat 
set download_count = download_count + 1, updated_at = now()
where dataset_id = #{datasetId}

mapper.select:
select count(*)
from sd_dataset_view_log
where dataset_id = #{datasetId}
and user_id = #{userId}
and created_at >= #{fromTime}

select count(*)
from sd_dataset_view_log
where dataset_id = #{datasetId}
and user_id is null
and view_ip = #{viewIp}
and created_at >= #{fromTime}
